        Set<String> cur = new HashSet<>();
        for (int i = 0; i <= s.length() - len; i++) {
            cur.add(s.substring(i, i + len));
        }
        if (common == null) {
            common = cur;
        } else {
            common.retainAll(cur);
            if (common.isEmpty()) {
                return false;
            }
        }
    }
    return common != null && !common.isEmpty();
}

