public static int countDoubles(int[] numbers) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0) {
            int half = n / 2;
            if (half != n) {
                if (freq.containsKey(half)) {
                    count++;
                }
            } else {
                if (freq.get(n) >= 2) {
                    count++;
                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> java.util.Arrays.stream(coord)
            .mapToObj(Integer::toString)
            .reduce((a, b) -> a + "," + b)
            .orElse("");

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start equals end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length != 2 * n) {
            // Skip malformed path entries
            continue;
        }
        int[] coordA = java.util.Arrays.copyOfRange(p, 0, n);
        int[] coordB = java.util.Arrays.copyOfRange(p, n, 2 * n);
        String keyA = coordKey.apply(coordA);
        String keyB = coordKey.apply(coordB);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // BFS from start to end
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || paths == null
            || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    // Interpret start and end as single vertex identifiers
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) continue;
        int u = p[0], v = p[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj[u].add(v);
        adj[v].add(u); // assuming undirected
    }

    // BFS to find path
    boolean[] visited = new boolean[n];
    java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    visited[startNode] = true;
    queue.add(startNode);

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adj[curr]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

