    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path.length < 4) continue;
            String p1 = path[0] + "," + path[1];
            String p2 = path[2] + "," + path[3];
            graph.computeIfAbsent(p1, k -> new java.util.ArrayList<>()).add(p2);
            graph.computeIfAbsent(p2, k -> new java.util.ArrayList<>()).add(p1);
        }
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neigh = graph.get(current);
        if (neigh != null) {
            for (String next : neigh) {
                if (visited.contains(next)) continue;
                if (next.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(next);
                queue.add(next);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Quick check if start and end are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list for graph; keys are "x,y" strings
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 4) {
            continue; // Skip invalid entries
        }
        String a = path[0] + "," + path[1];
        String b = path[2] + "," + path[3];
        adjacency.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adjacency.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbours = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbour : neighbours) {
            if (neighbour.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbour)) {
                visited.add(neighbour);
                queue.add(neighbour);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a string key
    java.util.function.IntFunction<String> coordKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    for (int[] path : paths) {
        // Expect each path to specify two endpoints: first n values for one node, next n for the other
        if (path.length != 2 * n) continue; // skip malformed entries
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String keyA = coordKey.apply(a);
        String keyB = coordKey.apply(b);
        graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // If start or end not present in graph, but they might still connect via implicit adjacency (by coordinates difference 1)
    // We'll handle implicit adjacency by checking neighboring coordinates on the fly during DFS/BFS.
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    stack.push(startKey);
    visited.add(startKey);

    while (!stack.isEmpty()) {
        String currentKey = stack.pop();
        if (currentKey.equals(endKey)) {
            return "can be travelled";
        }
        // Explore explicit neighbors in the graph
        java.util.List<String> neighbors = graph.getOrDefault(currentKey, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                stack.push(nb);
            }
        }
        // Explore implicit neighbors: coordinates that differ by ±1 in exactly one dimension
        int[] current = start; // placeholder to reuse array
        // Convert currentKey back to array
        String[] parts = currentKey.split(",");
        for (int i = 0; i < n; i++) {
            current[i] = Integer.parseInt(parts[i]);
        }
        for (int i = 0; i < n; i++) {
            for (int delta : new int[]{-1, 1}) {
                int[] neighbor = current.clone();
                neighbor[i] += delta;
                // Assuming we don't have bounds, but we treat all integer coords as valid
                String neighborKey = coordKey.apply(neighbor);
                if (!visited.contains(neighborKey)) {
                    visited.add(neighborKey);
                    // If it's the end, we can stop early
                    if (neighborKey.equals(endKey)) {
                        return "can be travelled";
                    }
                    // If it exists in graph, push onto stack; otherwise we still explore only implicit neighbors,
                    // but to avoid infinite expansion, only push if it is reachable via a defined path.
                    if (graph.containsKey(neighborKey)) {
                        stack.push(neighborKey);
                    }
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
