public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }

    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For other remainders, count[r] must equal count[k - r]
    for (int r = 1; r < k; r++) {
        if (r == k - r) {
            // already handled when k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) return false;
    int n = arr.length;
    if ((n & 1) == 1) return false; // odd length cannot form pairs
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // remainder 0 must have even count
    if (freq[0] % 2 != 0) return false;
    // if k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // Check other complementary remainders
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r == complement) continue; // handled above for even k
        if (freq[r] != freq[complement]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) return false;
    int[] cnt = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;
        cnt[r]++;
    }
    if (cnt[0] % 2 != 0) return false;
    if (k % 2 == 0 && cnt[k / 2] % 2 != 0) return false;
    int upper = k / 2;
    for (int r = 1; r <= upper; r++) {
        if (r == k - r) continue; // when k is even, handled already
        if (cnt[r] != cnt[k - r]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false;
    int[] freq = new int[k];
    for (int val : arr) {
        int rem = ((val % k) + k) % k;
        freq[rem]++;
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    for (int r = 1; r <= (k - 1) / 2; r++) {
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int nei : adj.get(node)) {
        if (nei == parent) continue;
        int sub = dfs(nei, node, adj, hasApple);
        if (sub > 0 || hasApple[nei]) {
            time += sub + 2;
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

