}

private boolean dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple, int[] res) {
    boolean hasSubApple = hasApple[node];
    for (int neighbour : adj.get(node)) {
        if (neighbour == parent) continue;
        boolean childHas = dfs(neighbour, node, adj, hasApple, res);
        if (childHas) {
            res[0] += 2;
            hasSubApple = true;
        }
    }
    return hasSubApple;
}

