private int dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] hasApple) {
    visited[node] = true;
    int time = 0;
    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            int t = dfs(neighbor, graph, visited, hasApple);
            if (t > 0) {
                time += t + 2;
            }
        }
    }
    return time;
}

public String sortString(String s) {
    int[] freq = new int[65536];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        for (int c = 0; c < 65536 && remaining > 0; c++) {
            if (freq[c] > 0) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
        for (int c = 65535; c >= 0 && remaining > 0; c--) {
            if (freq[c] > 0) {
                sb.append((char) c);
                freq[c]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    int[] cnt = new int[256];
    for (char ch : s.toCharArray()) {
        cnt[ch]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int total = s.length();
    while (total > 0) {
        // Ascending phase: pick smallest remaining, then smallest greater than last
        int last = -1;
        while (true) {
            int next = -1;
            for (int c = last + 1; c < 256; c++) {
                if (cnt[c] > 0) {
                    next = c;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            sb.append((char) next);
            cnt[next]--;
            total--;
            last = next;
        }
        if (total == 0) {
            break;
        }
        // Descending phase: pick largest remaining, then largest smaller than last
        int lastDesc = -1;
        for (int c = 255; c >= 0; c--) {
            if (cnt[c] > 0) {
                lastDesc = c;
                break;
            }
        }
        sb.append((char) lastDesc);
        cnt[lastDesc]--;
        total--;
        while (true) {
            int prev = -1;
            for (int c = lastDesc - 1; c >= 0; c--) {
                if (cnt[c] > 0) {
                    prev = c;
                    break;
                }
            }
            if (prev == -1) {
                break;
            }
            sb.append((char) prev);
            cnt[prev]--;
            total--;
            lastDesc = prev;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    java.util.TreeMap<Character,Integer> map = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        map.put(ch, map.getOrDefault(ch, 0) + 1);
    }
    StringBuilder res = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Increase sequence
        java.util.Map.Entry<Character,Integer> entry = map.firstEntry();
        char c = entry.getKey();
        res.append(c);
        int cnt = entry.getValue() - 1;
        if (cnt == 0) map.remove(c); else map.put(c, cnt);
        remaining--;
        char last = c;

        while (true) {
            java.util.Map.Entry<Character,Integer> next = map.higherEntry(last);
            if (next == null) break;
            c = next.getKey();
            res.append(c);
            cnt = next.getValue() - 1;
            if (cnt == 0) map.remove(c); else map.put(c, cnt);
            remaining--;
            last = c;
        }

        if (remaining == 0) break;

        // Decrease sequence
        entry = map.lastEntry();
        c = entry.getKey();
        res.append(c);
        cnt = entry.getValue() - 1;
        if (cnt == 0) map.remove(c); else map.put(c, cnt);
        remaining--;
        last = c;

        while (true) {
            java.util.Map.Entry<Character,Integer> prev = map.lowerEntry(last);
            if (prev == null) break;
            c = prev.getKey();
            res.append(c);
            cnt = prev.getValue() - 1;
            if (cnt == 0) map.remove(c); else map.put(c, cnt);
            remaining--;
            last = c;
        }
    }
    return res.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    // dp[k] stores all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (!dp[k].isEmpty()) {
                for (int s : dp[k]) {
                    dp[k + 1].add(s + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((sum * k) % n != 0) continue;
        int target = (sum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long total = 0;
    for (int num : nums) total += num;
    // dp[size] holds all possible sums with 'size' elements
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0L);
    for (int num : nums) {
        for (int size = n; size >= 1; size--) {
            for (Long s : dp[size - 1]) {
                long newSum = s + num;
                if (size <= n / 2) { // we only need to check up to n/2 to avoid duplicate work
                    long targetSum = (total * size) / n;
                    if ((total * size) % n == 0 && newSum == targetSum) return true;
                } else {
                    long targetSum = (total * size) / n;
                    if ((total * size) % n == 0 && newSum == targetSum) return true;
                }
                dp[size].add(newSum);
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
