    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[size] holds all possible sums of subsets of length size
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        for (int size = n - 1; size >= 0; size--) {
            for (int sum : dp[size]) {
                dp[size + 1].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;

    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0);

    for (int val : nums) {
        for (int k = n - 1; k >= 0; k--) {
            HashSet<Integer> cur = dp[k];
            if (cur == null) continue;
            HashSet<Integer> next = dp[k + 1];
            if (next == null) next = new HashSet<>();
            for (int s : cur) {
                next.add(s + val);
            }
            dp[k + 1] = next;
        }
    }

    for (int k = 1; k <= n - 1; k++) {
        HashSet<Integer> sums = dp[k];
        if (sums == null) continue;
        for (int sum : sums) {
            // Check if average of subset == average of whole array
            if (sum * n == totalSum * k) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = cost[0];
    int prev1 = cost[1];

    for (int i = 2; i < n; i++) {
        int current = Math.min(prev1 + cost[i], prev2 + cost[i]);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;

    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    int current = 0;

    for (int i = 2; i <= n; i++) {
        current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = current;
    }
    return current;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // min cost to reach step i-2
    int prev1 = 0; // min cost to reach step i-1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev2 + cost[i - 2], prev1 + cost[i - 1]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;
    int n = cost.length;
    int dp0 = 0; // cost to reach step 0
    int dp1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int current = Math.min(dp0 + cost[i - 2], dp1 + cost[i - 1]);
        dp0 = dp1;
        dp1 = current;
    }
    return dp1;
}

