public boolean hasAllCodes(String s, int k) {
    if (k <= 0 || s == null) return false;
    int n = s.length();
    if (n < k) return false;

    int totalCodes = 1 << k;          // number of possible k-length binary strings
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;         // keep only k bits
    int code = 0;
    int count = 0;

    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0'); // build sliding integer
        if (i >= k - 1) { // once we have a full k-length window
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == totalCodes) return true; // all codes found
            }
        }
    }
    return false; // if we exit loop without finding all codes
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    // Build the first value
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    // Slide the window
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) return true; // early exit
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k || n - k + 1 < (1 << k)) return false;
    int mask = 0;
    int allMask = (1 << k) - 1;
    boolean[] seen = new boolean[1 << k];
    int seenCount = 0;
    for (int i = 0; i < n; i++) {
        int bit = s.charAt(i) - '0';
        mask = ((mask << 1) | bit) & allMask;
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == (1 << k)) return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int count = 1;
    int maskLimit = total - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k; // number of all possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1; // keep only k bits
    int curr = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        // shift current bits left and add current bit
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) { // only start recording once we have first full window
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) {
                    return true; // early exit if all codes are seen
                }
            }
        }
    }
    return count == total;
}

