    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                answer++; // insert '(' before this ')'
            }
        }
    }
    answer += balance; // insert ')' for remaining '('
    return answer;
}

