}

public int minInsertions(String s) {
    int add = 0;      // number of '(' we need to insert before ')'
    int need = 0;     // number of ')' we need to insert after '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else { // c == ')'
            if (need > 0) {
                need--;
            } else {
                add++;
            }
        }
    }
    return add + need;
}

public int minOperations(int n) {
    int t = n / 2;           // floor(n/2)
    return t * (n - t);
}

public int minOperations(int n) {
    int half = n / 2;
    if (n % 2 == 0) {
        return half * half;
    } else {
        int m = half; // (n-1)/2
        return m * (m + 1);
    }
}

public int minOperations(int n) {
    long k = n / 2L;
    long res = (n % 2 == 0) ? k * k : k * (k + 1);
    return (int) res;
}

public int minOperations(int n) {
    int target = n;
    int ops = 0;
    for (int i = 0; i < n; i++) {
        int diff = (2 * i + 1) - target;
        if (diff > 0) {
            ops += diff;
        }
    }
    return ops;
}

public int minOperations(int n) {
    int target = n;
    int ops = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        if (value > target) {
            ops += value - target;
        }
    }
    return ops;
}

