public int kthFactor(int n, int k) {
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int paired = n / i;
            if (paired != i) {
                large.add(paired);
            }
        }
    }
    // Combine small factors in ascending order and large factors in ascending order
    Collections.reverse(large);
    List<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    if (k <= all.size()) {
        return all.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> big = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i * i != n) {
                big.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(big);
    int total = small.size() + big.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return big.get(k - small.size() - 1);
    }
}

