public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    java.util.Stack<Integer> high = new java.util.Stack<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                high.push(other);
            }
        }
    }
    while (!high.isEmpty()) {
        factors.add(high.pop());
    }
    if (k > 0 && k <= factors.size()) {
        return factors.get(k - 1);
    }
    return -1;
}

