public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int x : nums) {
        int newOnes = (ones ^ x) & ~twos;
        int newTwos = (twos ^ x) & ~newOnes;
        ones = newOnes;
        twos = newTwos;
    }
    return ones;
}

