    int result = 0;
    for (int i = 0; i < 32; i++) {
        int mask = 1 << i;
        int bitSum = 0;
        for (int num : nums) {
            if ((num & mask) != 0) {
                bitSum++;
            }
        }
        if (bitSum % 3 != 0) {
            result |= mask;
        }
    }
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low == 0 && high >= 0) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long curr = queue.poll();
        if (curr > high) {
            continue;
        }
        if (curr >= low) {
            result.add((int) curr);
        }
        int lastDigit = (int) (curr % 10);
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low == 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, low, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void dfs(int num, int low, int high, List<Integer> result) {
    if (num > high) {
        return;
    }
    if (num >= low) {
        result.add(num);
    }
    int lastDigit = num % 10;
    if (lastDigit > 0) {
        long newNum = 1L * num * 10 + (lastDigit - 1);
        if (newNum <= high) {
            dfs((int) newNum, low, high, result);
        }
    }
    if (lastDigit < 9) {
        long newNum = 1L * num * 10 + (lastDigit + 1);
        if (newNum <= high) {
            dfs((int) newNum, low, high, result);
        }
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    java.util.Set<Integer> resultSet = new java.util.TreeSet<>();
    if (low <= 0 && 0 <= high) {
        resultSet.add(0);
    }
    java.util.Deque<Long> queue = new java.util.ArrayDeque<>();
    for (int d = 1; d <= 9; d++) {
        if (d > high) {
            continue;
        }
        queue.add((long) d);
        while (!queue.isEmpty()) {
            long curr = queue.removeFirst();
            if (curr >= low && curr <= high) {
                resultSet.add((int) curr);
            }
            long lastDigit = curr % 10;
            long next1 = curr * 10 + (lastDigit - 1);
            if (lastDigit > 0 && next1 <= high) {
                queue.addLast(next1);
            }
            long next2 = curr * 10 + (lastDigit + 1);
            if (lastDigit < 9 && next2 <= high) {
                queue.addLast(next2);
            }
        }
    }
    return new java.util.ArrayList<>(resultSet);
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        int lastDigit = (int) (cur % 10);
        long nextBase = cur * 10;
        if (lastDigit > 0) {
            long nextNum = nextBase + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = nextBase + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    Queue<Long> queue = new ArrayDeque<>();
    for (int i = 0; i <= 9; i++) {
        if (i <= high) queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add((int) num);
        if (num == 0) continue; // avoid leading zero numbers
        int lastDigit = (int) (num % 10);
        long next;
        if (lastDigit > 0) {
            next = num * 10 + (lastDigit - 1);
            if (next <= high) queue.offer(next);
        }
        if (lastDigit < 9) {
            next = num * 10 + (lastDigit + 1);
            if (next <= high) queue.offer(next);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 1) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        factor *= 10;
    }
    return (int) count;
}

