public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int currMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                         Math.max(diag[i][j], anti[i][j]));
                if (currMax > maxLen) {
                    maxLen = currMax;
                }
            }
        }
    }
    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4]; // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;                     // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;                     // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;        // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1;   // anti-diagonal
                for (int d = 0; d < 4; d++) {
                    if (dp[i][j][d] > maxLen) {
                        maxLen = dp[i][j][d];
                    }
                }
            }
        }
    }
    return maxLen;
}

