public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    String number = Long.toString(value);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = number.length() - 1; i >= 0; i--) {
        sb.append(number.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    sb.reverse();
    String result = sb.toString();
    if (negative) {
        result = "-" + result;
    }
    return result;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    // Use long to correctly handle Integer.MIN_VALUE
    long absVal = Math.abs((long) n);
    String numStr = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();

    int length = numStr.length();
    int firstGroupLen = length % 3;
    if (firstGroupLen == 0 && length > 0) {
        firstGroupLen = 3;
    }

    sb.append(numStr.substring(0, firstGroupLen));
    for (int i = firstGroupLen; i < length; i += 3) {
        sb.append('.').append(numStr, i, i + 3);
    }

    String result = sb.toString();
    if (negative) {
        result = "-" + result;
    }
    return result;
}

public static String addThousandSeparator(int n) {
    long num = n;
    boolean negative = num < 0;
    if (negative) {
        num = -num;
    }

    if (num == 0) {
        return "0";
    }

    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append((int)(num % 10));
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long val = Math.abs((long) n);
    String s = Long.toString(val);
    int len = s.length();
    StringBuilder sb = new StringBuilder();
    int firstGroup = len % 3;
    if (firstGroup == 0) firstGroup = 3;
    sb.append(s, 0, firstGroup);
    for (int i = firstGroup; i < len; i += 3) {
        sb.append('.').append(s, i, i + 3);
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder rev = new StringBuilder();
    int digitCount = 0;
    while (num > 0) {
        rev.append(num % 10);
        num /= 10;
        digitCount++;
        if (digitCount % 3 == 0 && num > 0) {
            rev.append('.');
        }
    }
    rev.reverse();
    String result = rev.toString();
    if (negative) {
        result = "-" + result;
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);

    // Precompute which pairs have a perfect square sum
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = arr[i] + arr[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                can[i][j] = true;
            }
        }
    }

    int fullMask = (1 << n) - 1;
    java.util.Map<Integer, Integer> memo = new java.util.HashMap<>();

    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            // key = mask * (n+1) + (last+1) to handle last == -1
            int key = mask * (n + 1) + (last + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;

            if (mask == fullMask) {
                return 1;
            }

            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue; // already used
                if (last != -1 && !can[last][i]) continue; // adjacency not perfect square

                // Skip duplicates: if current number equals previous and previous hasn't been used in this state
                if (i > 0 && arr[i] == arr[i - 1] && (mask & (1 << (i - 1))) == 0) {
                    continue;
                }

                count += applyAsInt(mask | (1 << i), i);
            }

            memo.put(key, count);
            return count;
        }
    };

    return dfs.applyAsInt(0, -1);
}

