public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    // Precompute perfect squares up to 2*max
    boolean[] isSquare = new boolean[2 * max + 1];
    for (int i = 0; i * i < isSquare.length; i++) {
        isSquare[i * i] = true;
    }

    // Get unique values and frequencies
    java.util.Arrays.sort(A);
    java.util.List<Integer> valsList = new java.util.ArrayList<>();
    java.util.List<Integer> freqList = new java.util.ArrayList<>();
    for (int v : A) {
        if (valsList.isEmpty() || valsList.get(valsList.size() - 1) != v) {
            valsList.add(v);
            freqList.add(1);
        } else {
            freqList.set(freqList.size() - 1, freqList.get(freqList.size() - 1) + 1);
        }
    }
    int m = valsList.size();
    int[] vals = new int[m];
    int[] freqs = new int[m];
    for (int i = 0; i < m; i++) {
        vals[i] = valsList.get(i);
        freqs[i] = freqList.get(i);
    }

    java.util.Map<String, Integer> memo = new java.util.HashMap<>();

    java.util.function.BiFunction<Integer, int[], Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer lastIdx, int[] counts) {
            int remaining = 0;
            for (int c : counts) remaining += c;
            if (remaining == 0) return 1;

            // Construct memo key
            StringBuilder keyBuilder = new StringBuilder();
            if (lastIdx != -1) keyBuilder.append(lastIdx).append("|");
            for (int c : counts) keyBuilder.append(c).append(",");
            String key = keyBuilder.toString();

            if (memo.containsKey(key)) return memo.get(key);

            int total = 0;
            for (int i = 0; i < m; i++) {
                if (counts[i] == 0) continue;
                if (lastIdx != -1 && !isSquare[vals[lastIdx] + vals[i]]) continue;
                counts[i]--;
                total += apply(i, counts);
                counts[i]++;
            }
            memo.put(key, total);
            return total;
        }
    };

    return dfs.apply(-1, freqs);
}

