public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    Arrays.sort(A);
    boolean[] used = new boolean[n];
    final int[] count = {0};

    java.util.function.IntUnaryOperator isSquare = sum -> {
        int r = (int) Math.sqrt(sum);
        return r * r == sum ? 1 : 0;
    };

    java.util.function.BiConsumer<Integer, Integer> dfs = null;
    dfs = (depth, prev) -> {
        if (depth == n) {
            count[0]++;
            return;
        }
        int lastUsed = -1;
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            if (A[i] == lastUsed) continue; // skip duplicate numbers at the same recursion level
            if (depth > 0 && isSquare.applyAsInt(prev + A[i]) == 0) continue;
            used[i] = true;
            lastUsed = A[i];
            dfs.accept(depth + 1, A[i]);
            used[i] = false;
        }
    };

    dfs.accept(0, 0);
    return count[0];
}

public static int squarePermutations(int[] A) {
    // Count frequencies of each distinct value
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }
    int m = freqMap.size();
    int[] vals = new int[m];
    int[] counts = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        vals[idx] = e.getKey();
        counts[idx] = e.getValue();
        idx++;
    }
    // Precompute if sum of two values is a perfect square
    boolean[][] adj = new boolean[m][m];
    java.util.HashSet<Integer> squareSet = new java.util.HashSet<>();
    int maxSum = 0;
    for (int v : vals) maxSum += 2 * v;
    for (int s = 0; s * s <= maxSum; s++) squareSet.add(s * s);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            adj[i][j] = squareSet.contains(vals[i] + vals[j]);
        }
    }
    java.util.Map<String, Long> memo = new java.util.HashMap<>();
    long dfs = dfs(-1, counts, adj, memo);
    return (int) dfs;
}

private static long dfs(int last, int[] counts, boolean[][] adj,
                       java.util.Map<String, Long> memo) {
    // Check if all counts are zero
    boolean done = true;
    for (int c : counts) if (c > 0) { done = false; break; }
    if (done) return 1;
    // Build key
    StringBuilder sb = new StringBuilder();
    sb.append(last).append('#');
    for (int c : counts) sb.append(c).append(',');
    String key = sb.toString();
    if (memo.containsKey(key)) return memo.get(key);
    long res = 0;
    int m = counts.length;
    for (int i = 0; i < m; i++) {
        if (counts[i] == 0) continue;
        if (last == -1 || adj[last][i]) {
            counts[i]--;
            res += dfs(i, counts, adj, memo);
            counts[i]++; // backtrack
        }
    }
    memo.put(key, res);
    return res;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0; // number of elements in stack
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top > 0 && currentHeight < heights[stack[top - 1]]) {
            int h = heights[stack[--top]];
            int width = (top == 0) ? i : i - stack[top - 1] - 1;
            int area = h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

