public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) { // even sum -> traverse from endRow down to startRow
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else { // odd sum -> traverse from startRow up to endRow
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    for (int d = 0; d < m + n - 1; d++) {
        boolean up = d % 2 == 0;
        int r = up ? Math.min(d, m - 1) : Math.max(0, d - n + 1);
        int c = d - r;
        while (r >= 0 && r < m && c >= 0 && c < n) {
            res[idx++] = mat[r][c];
            if (up) {
                r--;
                c++;
            } else {
                r++;
                c--;
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int start = Math.max(0, sum - n + 1);
        int end = Math.min(sum, m - 1);
        if ((sum & 1) == 0) { // even sum: traverse from bottom to top
            for (int i = end; i >= start; i--) {
                result[index++] = mat[i][sum - i];
            }
        } else { // odd sum: traverse from top to bottom
            for (int i = start; i <= end; i++) {
                result[index++] = mat[i][sum - i];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= rows + cols - 2; sum++) {
        int startRow = Math.min(sum, rows - 1);
        int endRow = Math.max(0, sum - (cols - 1));
        if (sum % 2 == 0) {
            for (int r = startRow; r >= endRow; r--) {
                int c = sum - r;
                result[idx++] = mat[r][c];
            }
        } else {
            for (int r = endRow; r <= startRow; r++) {
                int c = sum - r;
                result[idx++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

