public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 1;
    while (i > 0 && digits[i - 1] >= digits[i]) {
        i--;
    }
    if (i <= 0) {
        return -1;
    }
    int leftPivot = i - 1;
    int right = digits.length - 1;
    while (digits[right] <= digits[leftPivot]) {
        right--;
    }
    char temp = digits[leftPivot];
    digits[leftPivot] = digits[right];
    digits[right] = temp;
    for (int l = i, r = digits.length - 1; l < r; l++, r--) {
        char t = digits[l];
        digits[l] = digits[r];
        digits[r] = t;
    }
    int result = Integer.parseInt(new String(digits));
    return result > n ? result : -1;
}

public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }

    // Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // No higher permutation
    }

    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the subarray from i+1 to the end
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }

    if (result > Integer.MAX_VALUE) {
        return -1; // Overflow case, not a valid int
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    return build(n, n);
}

private static List<String> build(int remaining, int total) {
    if (remaining == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (remaining == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    List<String> sub = build(remaining - 2, total);
    List<String> result = new ArrayList<>();
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };

    for (String s : sub) {
        for (char[] pair : pairs) {
            if (remaining == total && pair[0] == '0') {
                continue; // avoid leading zero
            }
            StringBuilder sb = new StringBuilder();
            sb.append(pair[0]).append(s).append(pair[1]);
            result.add(sb.toString());
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
