}

private static List<String> build(int n, boolean outermost) {
    if (n == 0) {
        List<String> res = new ArrayList<>();
        res.add("");
        return res;
    }
    if (n == 1) {
        List<String> res = new ArrayList<>();
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> sub = build(n - 2, false);
    List<String> result = new ArrayList<>();
    char[] left = {'0', '1', '6', '8', '9'};
    char[] right = {'0', '1', '9', '8', '6'};
    for (String inner : sub) {
        for (int i = 0; i < left.length; i++) {
            if (outermost && left[i] == '0') {
                continue;
            }
            result.add(left[i] + inner + right[i]);
        }
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    return build(n, n);
}

private static java.util.List<String> build(int n, int m) {
    java.util.List<String> res = new java.util.ArrayList<>();
    if (n == 0) {
        res.add("");
        return res;
    }
    if (n == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    java.util.List<String> inner = build(n - 2, m);
    for (String s : inner) {
        if (n != m) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    char[] midDigits;
    if (n % 2 == 1) {
        midDigits = new char[]{'0','1','8'};
    } else {
        midDigits = new char[0];
    }
    char[] chars = new char[n];
    backtrack(0, n-1, chars, pairs, midDigits, result);
    return result;
}

private static void backtrack(int left, int right, char[] chars, char[][] pairs, char[] midDigits, List<String> result) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    if (left == right) {
        for (char d : midDigits) {
            chars[left] = d;
            result.add(new String(chars));
        }
        return;
    }
    for (char[] p : pairs) {
        if (left == 0 && n > 1 && p[0] == '0') continue; // skip leading zero for length >1, n is not available here
        chars[left] = p[0];
        chars[right] = p[1];
        backtrack(left + 1, right - 1, chars, pairs, midDigits, result);
    }
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new java.util.ArrayList<>();
    }
    return generate(n, n);
}

private static java.util.List<String> generate(int currLen, int totalLen) {
    if (currLen == 0) {
        java.util.List<String> base = new java.util.ArrayList<>(1);
        base.add("");
        return base;
    }
    if (currLen == 1) {
        java.util.List<String> base = new java.util.ArrayList<>(3);
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    java.util.List<String> prev = generate(currLen - 2, totalLen);
    java.util.List<String> result = new java.util.ArrayList<>(prev.size() * 5);
    for (String s : prev) {
        if (currLen != totalLen) { // skip leading zero pair for the outermost layer
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check for duplicate points
    if (x1 == x2 && y1 == y2) return false;
    if (x1 == x3 && y1 == y3) return false;
    if (x2 == x3 && y2 == y3) return false;

    // Calculate the signed area (cross product)
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    return cross != 0;
}

