public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
            prev = c;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

