public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    long cur = 1;
    while (res.size() < n) {
        res.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur += 1;
        } else {
            while ((cur / 10) % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur += 1;
        }
    }
    return res;
}

private static void dfs(int curr, int n, java.util.List<Integer> res) {
    if (curr > n) return;
    res.add(curr);
    for (int i = 0; i < 10; i++) {
        long next = (long) curr * 10 + i;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    int curr = 1;
    for (int i = 0; i < n; i++) {
        res.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr++;
        } else {
            while (curr % 10 == 9) {
                curr /= 10;
            }
            curr++;
        }
    }
    return res;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        if (i > n) {
            break;
        }
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    if (current > n / 10) {
        return;
    }
    for (int i = 0; i < 10; i++) {
        int next = current * 10 + i;
        if (next > n) {
            break;
        }
        dfs(next, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr <= n / 10) {
            curr *= 10;  // go deeper to the next level
        } else {
            // if we cannot go deeper, move to the next sibling
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;  // climb up until we can increment
            }
            curr++;  // move to the next number
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

